#!/usr/bin/env node
import { AutoMovieLegacyImporter } from "@automovie/production";
import {
  AUTO_MOVIE_CONTRACT_BASELINE_PATH,
  type IAutoMovieContractBaseline,
  applyAutoMovieContractMigrationPlan,
  autoMovieContractTargetSources,
  planAutoMovieContractMigration,
  planAutoMovieProjectDeliveryTocs,
  publishFiles,
  renderScaffold,
} from "@automovie/template";
import { spawnSync } from "node:child_process";
import * as fs from "node:fs";
import * as path from "node:path";

import { dispatchAutoMovieCommandArguments } from "./commandArguments";

const USAGE = `automovie: scaffold an automovie project

Usage:
  npx create-automovie <directory> --language <chinese|english|japanese|korean> [--force]
  npx automovie start <directory> --language <chinese|english|japanese|korean> [--force]
  npx automovie sync
  npx automovie verify
  npx automovie contracts migrate [--dry-run]
  npx automovie toc [--check]
  npx automovie migrate <directory> [--dry-run | --rollback]
  npx automovie render <all|plan|run|status|verify|finalize|gc> [options]

Commands:
  start <directory>   Create <directory> and lay down the blank scaffold:
                      production skill, typed source branches, deterministic
                      compiler, local viewer, capture, tests, and evidence gates.
  sync                Overwrite generated agent instructions from the installed
                      template and tracked production evidence declaration.
  verify              Reopen generated bytes, render receipts, and delivery
                      media without modifying project state.
  contracts migrate   Plan or apply a scaffold contract-baseline migration.
  toc                  Generate canonical script and screenplay index links.
  migrate <directory> Plan or apply a non-destructive legacy v1 import.
  render <action>     Run the current project's resumable render job.

Options:
  --force             Scaffold into a non-empty directory (start only).
  --language <name>   Install exactly one production-authoring language pack.
  --dry-run           Print the immutable legacy import plan (migrate only).
  --rollback          Remove one untouched import (migrate only).
  --check             Refuse a stale delivery table of contents (toc only).
  --chunk-frames <n>  Positive render chunk size (all, plan, or run only).
  --deliverable <id>  Render one deliverable (all or run only).
  --tier <name>       Select proxy or final (all, plan, run, status, verify,
                      or finalize only).
  --workers <n>       Positive render worker count (all or run only).
  --apply             Apply render garbage collection (gc only).
  -h, --help          Show this help as a standalone request.
  -v, --version       Print the version as a standalone request.
`;

/**
 * This package's version, read at runtime from the sibling `package.json`
 * (`require`, not an `import`, so it stays outside `rootDir`). `__dirname`
 * resolves to `src` under ttsx and `lib` when published; the file sits one
 * level up in both.
 */
const packageVersion = (): string =>
  (require(path.join(__dirname, "..", "package.json")) as { version: string })
    .version;

/** Derive a valid npm package name from the target directory's basename. */
const projectNameOf = (targetDir: string): string =>
  path
    .basename(targetDir)
    .toLowerCase()
    .replace(/[^a-z0-9._-]+/g, "-")
    .replace(/^[-.]+|[-.]+$/g, "") || "automovie-project";

