export const run = (argv: readonly string[]): number => {
  try {
    return dispatchAutoMovieCommandArguments(argv.slice(2), (command) => {
      if (command.command === "help") {
        process.stdout.write(USAGE);
        return 0;
      }
      if (command.command === "version") {
        process.stdout.write(`${packageVersion()}\n`);
        return 0;
      }
      if (command.command === "render")
        return runProjectScript("render.ts", command.arguments);
      if (command.command === "sync" || command.command === "verify")
        return runProjectScript(`${command.command}.ts`, []);

      if (command.command === "toc") {
        const root = process.cwd();
        const files = readMarkdownFiles(path.join(root, "docs"), root);
        const plan = planAutoMovieProjectDeliveryTocs({
          check: command.check,
          files,
        });
        if (plan.diagnostics.length !== 0)
          throw new Error(plan.diagnostics.join("\n"));
        for (const [relative, source] of Object.entries(plan.files))
          if (files[relative] !== source)
            fs.writeFileSync(path.join(root, relative), source, "utf8");
        process.stdout.write(
          `${command.check ? "Checked" : "Updated"} delivery table of contents.\n`,
        );
        return 0;
      }

      if (command.command === "contracts") {
        const root = process.cwd();
        const baselineFile = path.join(root, AUTO_MOVIE_CONTRACT_BASELINE_PATH);
        const from = JSON.parse(
          fs.readFileSync(baselineFile, "utf8"),
        ) as IAutoMovieContractBaseline;
        const manifest = JSON.parse(
          fs.readFileSync(path.join(root, "package.json"), "utf8"),
        ) as { name?: string };
        const targetFiles = renderScaffold({
          language: from.language,
          name: manifest.name ?? path.basename(root),
        });
        const to = JSON.parse(
          targetFiles[AUTO_MOVIE_CONTRACT_BASELINE_PATH]!,
        ) as IAutoMovieContractBaseline;
        const targetSources = autoMovieContractTargetSources(targetFiles);
        const current = readContractFiles(root, from, to);
        const plan = planAutoMovieContractMigration({
          current,
          from,
          targetSources,
          to,
        });
        process.stdout.write(`${JSON.stringify(plan, null, 2)}\n`);
        if (command.dryRun) return plan.conflicts.length === 0 ? 0 : 1;
        if (plan.conflicts.length !== 0)
          throw new Error("Contract migration has unresolved conflicts.");
        const migrated = applyAutoMovieContractMigrationPlan(plan, current);
        for (const action of plan.actions) {
          if (action.action === "rename" || action.action === "remove") {
            const removed = path.join(
              root,
              action.action === "rename" ? action.from : action.path,
            );
            if (fs.existsSync(removed)) fs.unlinkSync(removed);
          }
          if (action.action !== "remove") {
            const target = path.join(root, action.path);
            fs.mkdirSync(path.dirname(target), { recursive: true });
            fs.writeFileSync(target, migrated[action.path]!, "utf8");
          }
        }
        fs.writeFileSync(
          baselineFile,
          targetFiles[AUTO_MOVIE_CONTRACT_BASELINE_PATH]!,
          "utf8",
        );
        return 0;
      }

      const targetDir = path.resolve(process.cwd(), command.directory);
      if (command.command === "migrate") {
        const importer = new AutoMovieLegacyImporter(targetDir);
        const output =
          command.mode === "rollback"
            ? importer.rollback()
            : command.mode === "dry-run"
              ? importer.plan()
              : importer.apply();
        process.stdout.write(`${JSON.stringify(output, null, 2)}\n`);
        return 0;
      }
      const files = renderScaffold({
        name: projectNameOf(targetDir),
        language: command.language,
      });
      const receipt = publishFiles(targetDir, files, { force: command.force });
      if (receipt.status !== "completed") {
        const failure = receipt.failure!;
        const outcome = failure.outcome;
        throw new Error(
          `scaffold publication ${receipt.status}: ${JSON.stringify({
            bytesWritten:
              outcome.status === "partial" ? outcome.bytesWritten : undefined,
            completed: receipt.completed.map(({ entry, parentIdentity }) => ({
              parentIdentity,
              relative: entry.relative,
            })),
            parentIdentity:
              outcome.status === "partial" ? outcome.parentIdentity : undefined,
            reason: outcome.status === "refused" ? outcome.reason : undefined,
            relative: failure.entry.relative,
            status: outcome.status,
          })}`,
          { cause: outcome.error },
        );
      }
      const written = receipt.completed.map(({ entry }) => entry.target);
      process.stdout.write(
        `Scaffolded ${written.length} files into ${targetDir}\n\n` +
          written
            .map((file) => `  ${path.relative(targetDir, file) || "."}`)
            .join("\n") +
          `\n\nNext:\n  cd ${command.directory}\n  npm install\n  npm run capture:install\n  npm run capture:doctor\n  npm run build\n  npm run lint:source\n  npm run lint\n  npm run render -- all --tier proxy\n  npm run viewer\n\n` +
          `Open http://127.0.0.1:5173 after the viewer starts.\n\n` +
          `README.md explains source ownership, evidence gates, and the local viewer.\n`,
      );
      return 0;
    });
  } catch (error) {
    process.stderr.write(
      `${error instanceof Error ? error.message : String(error)}\n`,
    );
    return 1;
  }
};

const readMarkdownFiles = (
  directory: string,
  root: string,
): Record<string, string> => {
  if (!fs.existsSync(directory)) return {};
  const files: Record<string, string> = {};
  for (const entry of fs
    .readdirSync(directory, { withFileTypes: true })
    .sort((left, right) =>
      left.name < right.name ? -1 : left.name > right.name ? 1 : 0,
    )) {
    const absolute = path.join(directory, entry.name);
    if (entry.isDirectory())
      Object.assign(files, readMarkdownFiles(absolute, root));
    else if (entry.isFile() && entry.name.endsWith(".md"))
      files[path.relative(root, absolute).split(path.sep).join("/")] =
        fs.readFileSync(absolute, "utf8");
  }
  return files;
};

const readContractFiles = (
  root: string,
  from: IAutoMovieContractBaseline,
  to: IAutoMovieContractBaseline,
): Record<string, string> => {
  const files: Record<string, string> = {};
  for (const relative of new Set([
    ...from.files.map((file) => file.path),
    ...to.files.map((file) => file.path),
  ])) {
    const file = path.join(root, relative);
    if (fs.existsSync(file)) files[relative] = fs.readFileSync(file, "utf8");
  }
  return files;
};

const runProjectScript = (
  scriptName: string,
  args: readonly string[],
): number => {
  const root = process.cwd();
  const script = path.join(root, "scripts", scriptName);
  // The launcher this repository ships, not a second TypeScript runner. The
  // other one reads the passwd database at its own module load on Windows,
  // before any project code exists, and dies where that syscall is denied.
  const launcher = path.join(
    root,
    "node_modules",
    "ttsc",
    "lib",
    "launcher",
    "ttsx.js",
  );
  if (fs.existsSync(script) === false || fs.existsSync(launcher) === false) {
    process.stderr.write(
      `The current project has no installed scripts/${scriptName} + TypeScript launcher. Run this command from a scaffolded project after npm install.\n`,
    );
    return 1;
  }
  const child = spawnSync(
    process.execPath,
    [launcher, "-P", path.join(root, "tsconfig.json"), script, ...args],
    { cwd: root, stdio: "inherit" },
  );
  return child.status ?? 1;
};

if (require.main === module) process.exitCode = run(process.argv);
